; ============================================================
; NTC program - generated by NTC BASIC (VB style BASIC to NTC)
; platform: cpcmin (Amstrad CPC - minimal firmware (own screen and keys, firmware for discs and ROMs)), starts in normal mode
; ============================================================

			DEVICE AMSTRADCPC6128		; for SAVEAMSDOS at the end
			org #0040

NTC_TERM	equ 0		; Option Terminal: 0 none, 1 VT52, 2 ANSI (CP/M)
NTC_STRMAX	equ 40		; the longest string (library buffers, temps)
NTC_MEMBANKS	equ 64		; Option Memory: the most 64K banks the Memory class looks for
NTC_ROMENABLE	equ 1		; Option RomEnable (cpcfw, cpcmin): the start code starts the ROMs
NTC_ROMLIB	equ 0		; 1 = the library is the keyword ROM (Library: ROM; ntcRomAsm builds it)
NTC_WINHOLE	equ 0		; 1 = the program is built round an Option Reserve range over the window #4000-#7FFF
NTC_BUFSIZE	equ 2048		; the library's buffer (ntc_buf: FileSystem, Memory.Copy): Option Buffer
NTC_CPMGFX	equ 0		; 1 = CP/M: Graphics draws on an Amstrad CPC's screen (2.2: #C000, Plus: block 1 from common memory)

ntc_start:
			jr ntc_start2
ntc_bk_sp:		dw 0			; #0042: main RAM's SP while a bank runs
ntc_bk_out:
			out (c), c		; #0044: BC = the other side's RAM setting
			jp ntc_bk_land		; #0046: main RAM switched in
ntc_bk_land:
			ld sp, (ntc_bk_sp)
			ret				; to where main RAM handed over
			ASSERT ntc_bk_out == #0044, "the bank switch must be at #0044"
ntc_start2:
			di
			ld (ntc_csp), sp
			ld a, (#BC77)		; Option RomEnable: start the ROMs again
			cp #DF			; AMSDOS has the cassette calls: they are running
			jp z, ntc_roms_on
			ei
			ld de, ntc_free		; the lowest address the ROMs may use (above the arrays)
			ld hl, #ABFF		; the highest (as usual for AMSDOS: it takes about #A700-#ABFF)
			ld c, 7
			call #BCCE		; KL INIT BACK: ROM 7 (DE / HL come back as the new limits)
			inc hl			; the first byte the ROMs took
			ld (ntc_roms_at), hl
			ld de, #A600
			or a
			sbc hl, de
			jp nc, ntc_roms_fit	; AMSDOS alone (or no more): as usual
			ld hl, ntc_roms_msg
			call ntc_roms_puts
			ld a, (ntc_roms_at + 1)
			call ntc_roms_hex
			ld a, (ntc_roms_at)
			call ntc_roms_hex
			ld hl, ntc_roms_msg2
			call ntc_roms_puts
			call #BB06		; KM WAIT CHAR
			rst 0			; (the machine starts again)
ntc_roms_puts:
			ld a, (hl)
			or a
			ret z
			call #BB5A		; TXT OUTPUT
			inc hl
			jr ntc_roms_puts
ntc_roms_hex:
			push af
			rrca
			rrca
			rrca
			rrca
			call ntc_roms_dig
			pop af
ntc_roms_dig:
			and 15
			add a, #90
			daa
			adc a, #40
			daa
			jp #BB5A
ntc_roms_at:	dw 0
ntc_roms_msg:	db "The ROMs' RAM reaches down to #", 0
ntc_roms_msg2:	db ": no room for this program", 13, 10, "(fewer ROMs, or a smaller program)", 13, 10, "Press a key", 13, 10, 0
ntc_roms_fit:
			di
			ASSERT ntc_free <= #A600, "Option RomEnable: the program and its arrays must end below #A600 (the ROMs take their RAM from #ABFF down)"
ntc_roms_on:
			ld a, 1
			ld (ntc_nmode), a		; normal mode: waits let interrupts in
			ld ix, ntc_go
			jp ntc_plat_irqon		; interrupt handler for normal mode
ntc_go:
			ld sp, main_thread
			ret

; ============================================================
; Main Thread
; ============================================================

main_thread:
			dw kw_scrinit		; mode 1, ROMs off, clear screen
			dw kw_bssinit, ntc_bss, ntc_bss_size		; the arrays: do they fit, clear them

			; main.bas 14: Print "1 started"
			dw kw_printzoscii
			dw glyph_31, glyph_20, glyph_73, glyph_74, glyph_61, glyph_72, glyph_74, glyph_65
			dw glyph_64, 1, 0		; "1 started\n"

			; main.bas 15: Wait
			dw p_wait_c

			; main.bas 16: Print "2 Capability LOAD"; FileSystem.Capability("LOAD"); " SAVE"; FileSystem.Capability("SAVE")
			dw fn_filesystem_capability, str0, var_filesystem_capability_capability
			dw kw_printzoscii
			dw glyph_32, glyph_20, glyph_43, glyph_61, glyph_70, glyph_61, glyph_62, glyph_69
			dw glyph_6C, glyph_69, glyph_74, glyph_79, glyph_20, glyph_4C, glyph_4F, glyph_41
			dw glyph_44, 0		; "2 Capability LOAD"
			dw kw_printint, var_filesystem_capability_capability
			dw fn_filesystem_capability, str1, var_filesystem_capability_capability
			dw kw_printzoscii
			dw glyph_20, glyph_53, glyph_41, glyph_56, glyph_45, 0		; " SAVE"
			dw kw_printint, var_filesystem_capability_capability
			dw kw_printnl

			; main.bas 17: Wait
			dw p_wait_c

			; main.bas 18: Print "3 Devices: "; FileSystem.Devices()
			dw fn_filesystem_devices, var_filesystem_devices_devices
			dw kw_printzoscii
			dw glyph_33, glyph_20, glyph_44, glyph_65, glyph_76, glyph_69, glyph_63, glyph_65
			dw glyph_73, glyph_3A, glyph_20, 0		; "3 Devices: "
			dw kw_printstrvar, var_filesystem_devices_devices
			dw kw_printnl

			; main.bas 19: Wait
			dw p_wait_c

			; main.bas 20: Print "4 CurrentDevice: "; FileSystem.CurrentDevice(); "  Volume: "; FileSystem.CurrentVolume()
			dw fn_filesystem_currentdevice, var_filesystem_currentdevice_currentdevice
			dw kw_printzoscii
			dw glyph_34, glyph_20, glyph_43, glyph_75, glyph_72, glyph_72, glyph_65, glyph_6E
			dw glyph_74, glyph_44, glyph_65, glyph_76, glyph_69, glyph_63, glyph_65, glyph_3A
			dw glyph_20, 0		; "4 CurrentDevice: "
			dw kw_printstrvar, var_filesystem_currentdevice_currentdevice
			dw fn_filesystem_currentvolume, var_filesystem_currentvolume_currentvolume
			dw kw_printzoscii
			dw glyph_20, glyph_20, glyph_56, glyph_6F, glyph_6C, glyph_75, glyph_6D, glyph_65
			dw glyph_3A, glyph_20, 0		; "  Volume: "
			dw kw_printstrvar, var_filesystem_currentvolume_currentvolume
			dw kw_printnl

			; main.bas 21: Wait
			dw p_wait_c

			; main.bas 22: For i = 0 To 9 : a(i) = 1000 - i * 50 : Next
			dw kw_ztov, var_i
for1_t:
			dw kw_mulvl, var_i, 50, tmp2
			dw kw_sublv, 1000, tmp2, tmp1
			dw kw_aset, arr_a, var_i, tmp1
			dw kw_next1l_n, var_i, 9, for1_t
for1_e:

			; main.bas 23: Print "5 Save STEP.DAT..."
			dw kw_printzoscii
			dw glyph_35, glyph_20, glyph_53, glyph_61, glyph_76, glyph_65, glyph_20, glyph_53
			dw glyph_54, glyph_45, glyph_50, glyph_2E, glyph_44, glyph_41, glyph_54, glyph_2E
			dw glyph_2E, glyph_2E, 1, 0		; "5 Save STEP.DAT...\n"

			; main.bas 24: Wait
			dw p_wait_c

			; main.bas 25: r = FileSystem.Save("STEP.DAT", VarPtr(a), 20)
			dw fn_filesystem_save, str2, vp_arr_a, lit_20, var_r

			; main.bas 26: Print "  Save gave"; r
			dw kw_printzoscii
			dw glyph_20, glyph_20, glyph_53, glyph_61, glyph_76, glyph_65, glyph_20, glyph_67
			dw glyph_61, glyph_76, glyph_65, 0		; "  Save gave"
			dw kw_printint, var_r
			dw kw_printnl

			; main.bas 27: Wait
			dw p_wait_c

			; main.bas 28: Print "6 Load STEP.DAT..."
			dw kw_printzoscii
			dw glyph_36, glyph_20, glyph_4C, glyph_6F, glyph_61, glyph_64, glyph_20, glyph_53
			dw glyph_54, glyph_45, glyph_50, glyph_2E, glyph_44, glyph_41, glyph_54, glyph_2E
			dw glyph_2E, glyph_2E, 1, 0		; "6 Load STEP.DAT...\n"

			; main.bas 29: Wait
			dw p_wait_c

			; main.bas 30: r = FileSystem.Load("STEP.DAT", VarPtr(b), 20)
			dw fn_filesystem_load, str2, vp_arr_b, lit_20, var_r

			; main.bas 31: Print "  Load gave"; r; ", "; b(0); " ... "; b(9)
			dw kw_printzoscii
			dw glyph_20, glyph_20, glyph_4C, glyph_6F, glyph_61, glyph_64, glyph_20, glyph_67
			dw glyph_61, glyph_76, glyph_65, 0		; "  Load gave"
			dw kw_printint, var_r
			dw kw_printzoscii
			dw glyph_2C, glyph_20, 0		; ", "
			dw kw_printint, arr_b
			dw kw_printzoscii
			dw glyph_20, glyph_2E, glyph_2E, glyph_2E, glyph_20, 0		; " ... "
			dw kw_printint, arr_b+18
			dw kw_printnl

			; main.bas 32: Print "7 done"
			dw kw_printzoscii
			dw glyph_37, glyph_20, glyph_64, glyph_6F, glyph_6E, glyph_65, 1, 0		; "7 done\n"

			; main.bas 33: End
			dw kw_printnl0
			dw kw_printzoscii
			dw glyph_50, glyph_72, glyph_65, glyph_73, glyph_73, glyph_20, glyph_61, glyph_20
			dw glyph_6B, glyph_65, glyph_79, glyph_20, glyph_74, glyph_6F, glyph_20, glyph_65
			dw glyph_6E, glyph_64, 0		; "Press a key to end"
			dw kw_waitkey
			dw kw_stop

; ============================================================
; sub wait (normal mode)
; ============================================================

p_wait:

			; main.bas 36: Print "  (press a key)"
			dw kw_printzoscii
			dw glyph_20, glyph_20, glyph_28, glyph_70, glyph_72, glyph_65, glyph_73, glyph_73
			dw glyph_20, glyph_61, glyph_20, glyph_6B, glyph_65, glyph_79, glyph_29, 1
			dw 0		; "  (press a key)\n"

			; main.bas 37: Do While Inkey <> 0 : Loop
do2_t:
			dw kw_inkey, tmp0
			dw kw_cpnevl, tmp0, 0
			dw kw_goto_iffalse_n, do2_e
			dw do2_t_go
do2_e:

			; main.bas 38: Do : Frame : Loop Until Inkey <> 0
do3_t:
			dw kw_frame
			dw kw_inkey, tmp0
			dw kw_cpnevl, tmp0, 0
			dw kw_goto_iffalse_n, do3_t
do3_e:
			dw p_wait_r

; ============================================================
; Jump stubs (code, ROMable)
;   label_go: GOTO label
;   label_gs: GOSUB label, return point -> label_rs (RAM)
;   label_rt: RETURN from label
;   p_name_c: call a procedure, p_name_r: end of it
;   turbo mode ends with ret, normal mode with jp ntc_xn
; ============================================================

do2_t_go:			ld sp, do2_t
			jp ntc_xn

p_wait_c:		; call wait (normal)
			ld (p_wait_rs), sp
			ld sp, p_wait
			jp ntc_xn
p_wait_r:		; end of wait
			ld sp, (p_wait_rs)
			jp ntc_xn

; ============================================================
; Inline assembly (#asm ... #endasm)
; ============================================================

fn_filesystem_capability:		; function capability (asm keyword), FileSystem.cls line 63
            pop hl		; FileSystem.cls 64
            pop de		; FileSystem.cls 65
            ld bc, fn_filesystem_capability_caps		; FileSystem.cls 66
            jp ntc_capfind		; FileSystem.cls 67
fn_filesystem_capability_caps:       db "LOAD", 0		; FileSystem.cls 68
            dw -1		; FileSystem.cls 69
            db "SAVE", 0		; FileSystem.cls 70
            dw -1		; FileSystem.cls 71
            db "SEQUENTIAL", 0		; FileSystem.cls 72
            dw -1		; FileSystem.cls 73
            db "DEVICES", 0		; FileSystem.cls 74
            dw -1		; FileSystem.cls 75
            db "VOLUMES", 0		; FileSystem.cls 76
            dw -1		; FileSystem.cls 77
            db "ROMDISC", 0		; FileSystem.cls 78
            dw -1		; FileSystem.cls 79
            db "MAXOPEN", 0		; FileSystem.cls 80
            dw 1		; FileSystem.cls 81
            db 0		; FileSystem.cls 82
			ret			; end of #asm

fn_filesystem_load:		; function load (asm keyword), FileSystem.cls line 110
            pop hl		; FileSystem.cls 111
            ld (fs_a1), hl		; FileSystem.cls 112
            pop hl		; FileSystem.cls 113
            ld e, (hl)		; FileSystem.cls 114
            inc hl		; FileSystem.cls 115
            ld d, (hl)		; FileSystem.cls 116
            ld (fs_a2), de		; FileSystem.cls 117
            pop hl		; FileSystem.cls 118
            ld e, (hl)		; FileSystem.cls 119
            inc hl		; FileSystem.cls 120
            ld d, (hl)		; FileSystem.cls 121
            ld (fs_a3), de		; FileSystem.cls 122
            pop hl		; FileSystem.cls 123
            ld (fs_res), hl		; FileSystem.cls 124
            ld hl, fs_load		; FileSystem.cls 125
            ld de, rd_load		; FileSystem.cls 126
            jp rd_route		; FileSystem.cls 127
			ret			; end of #asm

fn_filesystem_save:		; function save (asm keyword), FileSystem.cls line 154
            pop hl		; FileSystem.cls 155
            ld (fs_a1), hl		; FileSystem.cls 156
            pop hl		; FileSystem.cls 157
            ld e, (hl)		; FileSystem.cls 158
            inc hl		; FileSystem.cls 159
            ld d, (hl)		; FileSystem.cls 160
            ld (fs_a2), de		; FileSystem.cls 161
            pop hl		; FileSystem.cls 162
            ld e, (hl)		; FileSystem.cls 163
            inc hl		; FileSystem.cls 164
            ld d, (hl)		; FileSystem.cls 165
            ld (fs_a3), de		; FileSystem.cls 166
            pop hl		; FileSystem.cls 167
            ld (fs_res), hl		; FileSystem.cls 168
            ld hl, fs_save		; FileSystem.cls 169
            ld de, rd_ns		; FileSystem.cls 170
            jp rd_route		; FileSystem.cls 171
			ret			; end of #asm

fn_filesystem_devices:		; function devices (asm keyword), FileSystem.cls line 556
            pop hl		; FileSystem.cls 557
            ld (fs_res), hl		; FileSystem.cls 558
            ld hl, fs_devices		; FileSystem.cls 559
            jp fs_go0		; FileSystem.cls 560
			ret			; end of #asm

fn_filesystem_currentdevice:		; function currentdevice (asm keyword), FileSystem.cls line 566
            pop hl		; FileSystem.cls 567
            ld (fs_res), hl		; FileSystem.cls 568
            ld hl, fs_curdev		; FileSystem.cls 569
            jp fs_go0		; FileSystem.cls 570
			ret			; end of #asm

fn_filesystem_currentvolume:		; function currentvolume (asm keyword), FileSystem.cls line 599
            pop hl		; FileSystem.cls 600
            ld (fs_res), hl		; FileSystem.cls 601
            ld hl, fs_curvol		; FileSystem.cls 602
            jp fs_go0		; FileSystem.cls 603
			ret			; end of #asm


